+            Queue<ShardRouting> shards = e.getValue();
+            int sentRequests = Math.min(shards.size(), maxConcurrentRequests);
+            expectedRequestCounts.put(e.getKey(), sentRequests);
+            for (int i = 0; i < sentRequests; i++) {
+                shards.remove();
+            }
